    module_function

    # @param shape_type [Pptx::Enum::MSO_SHAPE]
    def for(shape_type)
      SPECS.fetch(Enum::MSO_SHAPE.fetch(shape_type).name) do
        raise ArgumentError, "no auto-shape spec for #{shape_type.inspect}"
      end
    end

    def basename(shape_type) = self.for(shape_type)[:basename]

    def default_adjustments(shape_type) = self.for(shape_type)[:default_adjustments]
  end
